import { TIERS } from './autonomy'
import { judgeFleet, type FleetAgent } from './fleet'
import { cx, pct } from './util'

export type AutonomyBoardProps = {
  title: string
  agents: FleetAgent[]
  /** Fixed clock for the verdicts. Defaults to the current time. */
  now?: string
  className?: string
}

/**
 * Every agent in one list: its tier, whether a person's agreement with it has earned a higher one, what its grants
 * and budget look like, and anything that needs a look. Each row is worked out from that agent's own cases, grants
 * and budget, and the eligible tag is a prompt for a person, not a promotion.
 */
export function AutonomyBoard({ title, agents, now, className }: AutonomyBoardProps) {
  const { rows, summary } = judgeFleet(agents, now)
  return (
    <section role="group" className={cx('ol', className)} aria-label={title}>
      <div className="ol-head-row">
        <strong>{title}</strong>
        <span className="ol-sub">{summary.text}</span>
      </div>
      {rows.length === 0 ? (
        <p className="ol-sub" style={{ margin: 0 }}>No agents.</p>
      ) : (
        <ul className="ol-fleetlist" aria-label="Agents">
          {rows.map((r) => {
            const a = r.autonomy
            const tier = TIERS.find((t) => t.id === r.agent.tier)
            return (
              <li key={r.agent.id} className="ol-fleetrow" data-flag={r.flags.some((f) => f.severity === 'bad') ? 'bad' : r.flags.length ? 'warn' : undefined}>
                <div className="ol-fleetname">
                  <strong>{r.agent.name}</strong>
                  <span className="ol-sub">{r.agent.tier} {tier?.name}</span>
                </div>
                <div className="ol-fleetgate">
                  <span className="ol-pill" data-tone={r.eligibleFor ? 'good' : r.demoteTo ? 'bad' : a.status === 'stay' ? 'warn' : undefined}>
                    {r.eligibleFor ? `Eligible for ${r.eligibleFor}` : r.demoteTo ? `Step down to ${r.demoteTo}` : a.status === 'collecting' ? 'Collecting cases' : a.status === 'stay' ? `Stay at ${r.agent.tier}` : 'Top tier'}
                  </span>
                  <span className="ol-sub">{a.n > 0 ? `${pct(a.observed, 0)} agreed, ${a.agree} of ${a.n}` : 'No cases yet'}</span>
                </div>
                <div className="ol-fleetnote">
                  {r.flags.length === 0 ? (
                    <span className="ol-sub">{r.grants ? r.grants.text : 'Nothing flagged.'}</span>
                  ) : (
                    r.flags.map((f) => <span key={f.kind + f.text} className="ol-pill" data-tone={f.severity}>{f.text}</span>)
                  )}
                </div>
              </li>
            )
          })}
        </ul>
      )}
    </section>
  )
}

// Rules for reading a fleet of agents at once. The point of each: every agent's row is worked out from its own
// cases, grants and budget by the same functions the single views use, so a row can never say more than its parts.
import { judgeAutonomy, nextTier, previousTier, type AutonomyCase, type AutonomyRule, type Judgement, type Tier } from './autonomy'
import { judgeBudget, type BudgetInput, type BudgetReport } from './budget'
import { judgeGrants, type Grant, type GrantSummary } from './permissions'

export type FleetAgent = {
  id: string
  name: string
  tier: Tier
  cases: AutonomyCase[]
  rule: AutonomyRule
  looks?: number
  grants?: Grant[]
  budget?: BudgetInput
}
export type AgentFlag = { kind: 'budget' | 'grant' | 'overrides' | 'demote'; text: string; severity: 'warn' | 'bad' }
export type AgentRow = {
  agent: FleetAgent
  autonomy: Judgement
  /** The tier this agent could be considered for, when the gate says eligible. */
  eligibleFor: Tier | null
  /** The tier to step down to, when the latest cases say the agent no longer meets the rule. */
  demoteTo: Tier | null
  grants?: GrantSummary
  budget?: BudgetReport
  flags: AgentFlag[]
}
export type FleetSummary = { agents: number; eligible: number; flagged: number; text: string }

const RECENT_MS = 7 * 24 * 3600 * 1000

/** Flagged agents first, worst flag first, then agents eligible to move up, then the rest by name. */
export function judgeFleet(agents: FleetAgent[], now?: string | Date): { rows: AgentRow[]; summary: FleetSummary } {
  const clock = (now ? new Date(now) : new Date()).getTime()
  const rows = agents.map((agent): AgentRow => {
    const autonomy = judgeAutonomy(agent.cases, agent.rule, agent.looks, agent.tier)
    const grants = agent.grants ? judgeGrants(agent.grants, now).summary : undefined
    const budget = agent.budget ? judgeBudget({ now, ...agent.budget }) : undefined
    const flags: AgentFlag[] = []
    if (budget?.status === 'over') flags.push({ kind: 'budget', text: budget.text, severity: 'bad' })
    else if (budget?.status === 'over-pace') flags.push({ kind: 'budget', text: budget.text, severity: 'bad' })
    else if (budget?.status === 'watch' || budget?.status === 'unreadable') flags.push({ kind: 'budget', text: budget.text, severity: 'warn' })
    if (grants && grants.counts.over) flags.push({ kind: 'grant', text: `${grants.counts.over} grant${grants.counts.over > 1 ? 's' : ''} over the limit.`, severity: 'bad' })
    if (grants && grants.counts.exhausted + grants.counts.expiring) flags.push({ kind: 'grant', text: `${grants.counts.exhausted + grants.counts.expiring} grant${grants.counts.exhausted + grants.counts.expiring > 1 ? 's' : ''} used up or expiring.`, severity: 'warn' })
    const recent = autonomy.recentOverrides.filter((c) => c.at && clock - new Date(c.at).getTime() <= RECENT_MS && new Date(c.at).getTime() <= clock)
    if (agent.tier !== 'T0' && recent.length >= 3) flags.push({ kind: 'overrides', text: `${recent.length} overrides in the last 7 days.`, severity: 'warn' })
    if (autonomy.status === 'demote') flags.unshift({ kind: 'demote', text: `Latest ${autonomy.recent?.n} cases agreed ${Math.round((autonomy.recent?.observed ?? 0) * 100)}%. Step down.`, severity: 'bad' })
    return { agent, autonomy, eligibleFor: autonomy.status === 'ready' ? nextTier(agent.tier) : null, demoteTo: autonomy.status === 'demote' ? previousTier(agent.tier) : null, grants, budget, flags }
  })
  const rank = (r: AgentRow) => (r.flags.some((f) => f.severity === 'bad') ? 0 : r.flags.length ? 1 : r.eligibleFor ? 2 : 3)
  rows.sort((a, b) => rank(a) - rank(b) || a.agent.name.localeCompare(b.agent.name))
  const flagged = rows.filter((r) => r.flags.length).length
  const eligible = rows.filter((r) => r.eligibleFor).length
  const parts = [`${rows.length} agent${rows.length === 1 ? '' : 's'}`]
  if (flagged) parts.push(`${flagged} need attention`)
  if (eligible) parts.push(`${eligible} eligible for a higher tier`)
  return { rows, summary: { agents: rows.length, eligible, flagged, text: parts.join(', ') } }
}
